/** The stored absence for one member, whether or not it currently applies. */
export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** One absence per member: setting it again replaces the previous one. */
export async function upsertAbsence(
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const values = {
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
    updatedAt: stamp,
  };

  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      ...values,
      createdAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: values,
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/** Drops `delegateUserId` from every absence in the org that names them. */
