import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
import "@/server/services/notification-service";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("redirects and drops delegate on removal", async () => {
  const t = await createTenant("abs");
  const now = Date.now();
  const a = await memberService.setAbsence(t.actors.member, {
    orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.admin,
    startsAt: new Date(now - 1000).toISOString() as never, endsAt: new Date(now + 60000).toISOString() as never, note: "hi",
  });
  expect(await memberService.getAbsence(t.actors.viewer, t.org.id, t.userIds.member)).toEqual(a);
